#pragma once

#include <mira/workflow_events.hpp>

#include <vector>

namespace mira::testing {

// Stable inputs for the wire compatibility fixture. The fixture is captured
// from the pre-refactor encoder, never regenerated by the test under test.
template <typename Event> Event workflow_event_sample() {
    Event event;
    const Id128 id{Id128::Bytes{1}};
    if constexpr (requires { event.run_id; })
        event.run_id = WorkflowRunId{id};
    if constexpr (requires { event.workflow_id; })
        event.workflow_id = WorkflowId{id};
    if constexpr (requires { event.step_id; })
        event.step_id = StepId{id};
    if constexpr (requires { event.patch_id; })
        event.patch_id = WorkflowPatchId{id};
    if constexpr (requires { event.decision_id; })
        event.decision_id = WorkflowDecisionId{id};
    if constexpr (requires { event.task_id; })
        event.task_id = TaskId{id};
    if constexpr (requires { event.dry_run_id; })
        event.dry_run_id = WorkflowRunId{id};
    if constexpr (requires { event.safe_summary; }) {
        event.safe_summary = "fixture \"quoted\" \\ path\nnext";
    }
    if constexpr (requires { event.reason_code; })
        event.reason_code = "validation-failed";
    return event;
}

inline std::vector<EventPayload> workflow_event_samples() {
    return {
        to_event_payload(workflow_event_sample<WorkflowRunStartedEvent>()),
        to_event_payload(workflow_event_sample<WorkflowStepStartedEvent>()),
        to_event_payload(workflow_event_sample<WorkflowStepSettledEvent>()),
        to_event_payload(workflow_event_sample<WorkflowRunSettledEvent>()),
        to_event_payload(workflow_event_sample<WorkflowPatchProposedEvent>()),
        to_event_payload(workflow_event_sample<WorkflowPatchAppliedEvent>()),
        to_event_payload(workflow_event_sample<WorkflowPatchRejectedEvent>()),
        to_event_payload(workflow_event_sample<WorkflowPolicySwitchedEvent>()),
        to_event_payload(workflow_event_sample<WorkflowDecisionRaisedEvent>()),
        to_event_payload(workflow_event_sample<WorkflowDecisionResolvedEvent>()),
        to_event_payload(workflow_event_sample<WorkflowPublishProposedEvent>()),
        to_event_payload(workflow_event_sample<WorkflowPublishAppliedEvent>()),
        to_event_payload(workflow_event_sample<WorkflowPublishRejectedEvent>()),
        to_event_payload(workflow_event_sample<WorkflowNavigationPlannedEvent>()),
        to_event_payload(workflow_event_sample<WorkflowNavigationObservedEvent>()),
        to_event_payload(workflow_event_sample<WorkflowEpisodeRecordedEvent>()),
        to_event_payload(workflow_event_sample<WorkflowLessonRecordedEvent>()),
        to_event_payload(workflow_event_sample<WorkflowRecoveryAttemptedEvent>()),
        to_event_payload(workflow_event_sample<WorkflowToolCompatDegradedEvent>()),
        to_event_payload(workflow_event_sample<WorkflowProceduresSyncedEvent>()),
    };
}

} // namespace mira::testing
